var documenterSearchIndex = {"docs":
[{"location":"internal/#Internal-docstrings","page":"Internal docstrings","title":"Internal docstrings","text":"","category":"section"},{"location":"internal/","page":"Internal docstrings","title":"Internal docstrings","text":"warning: Not public API\nThese functions are not part of the MultiDocumenter public API.","category":"page"},{"location":"internal/","page":"Internal docstrings","title":"Internal docstrings","text":"Modules = [MultiDocumenter.DocumenterTools]","category":"page"},{"location":"internal/#MultiDocumenter.DocumenterTools.FileInfo","page":"Internal docstrings","title":"MultiDocumenter.DocumenterTools.FileInfo","text":"struct FileInfo\n\nObjects of this type are passed as arguments to the callback of the walkdocs function. See walkdocs for information on how to interpret the docstrings.\n\n\n\n\n\n","category":"type"},{"location":"internal/#MultiDocumenter.DocumenterTools.get_meta_redirect_url-Tuple{AbstractString}","page":"Internal docstrings","title":"MultiDocumenter.DocumenterTools.get_meta_redirect_url","text":"Parses the HTML file at indexhtml_path and tries to extract the url=... value of the redirect <meta http-equiv=\"refresh\" ...> tag.\n\n\n\n\n\n","category":"method"},{"location":"internal/#MultiDocumenter.DocumenterTools.isdochtml-Tuple{MultiDocumenter.DocumenterTools.FileInfo}","page":"Internal docstrings","title":"MultiDocumenter.DocumenterTools.isdochtml","text":"isdochtml(::Fileinfo) -> Bool\n\nChecks if the file is a Documenter-generated HTML file.\n\n\n\n\n\n","category":"method"},{"location":"internal/#MultiDocumenter.DocumenterTools.update_canonical_links-Tuple{AbstractString}","page":"Internal docstrings","title":"MultiDocumenter.DocumenterTools.update_canonical_links","text":"Takes the multi-versioned Documenter site in docs_directory and updates the HTML canonical URLs to point to canonical.\n\n\n\n\n\n","category":"method"},{"location":"internal/#MultiDocumenter.DocumenterTools.update_canonical_links_for_version-Tuple{AbstractString}","page":"Internal docstrings","title":"MultiDocumenter.DocumenterTools.update_canonical_links_for_version","text":"DocumenterTools.update_canonical_links_for_build(\n    docs_directory::AbstractString;\n    canonical::AbstractString,\n)\n\ncanonical: corresponds to the canonical attribute of Documenter.HTML, specifying the root of the canonical URL.\n\n\n\n\n\n","category":"method"},{"location":"internal/#MultiDocumenter.DocumenterTools.walkdocs","page":"Internal docstrings","title":"MultiDocumenter.DocumenterTools.walkdocs","text":"walkdocs(f, dir::AbstractString[, filter_cb]; collect::Bool=false)\n\nTakes a directory dir, which is assumed to contain Documenter-generated documentation, walks over all the files and calls f on each of the files it find. Optionally, a filter_cb(::FileInfo) function can be passed to only call f on files for which it returns true.\n\nf and filter_cb will be called with a single object that has the following fields (all strings):\n\n.root: the root directory of the walk, i.e. dir (but as an absolute path)\n.filename: file name\n.relpath: path to the file, relative to dir\n.fullpath: absolute path to the file\n\nSee also the FileInfo struct.\n\nIf collect = true is set, the function also \"collects\" all the return values from f from each of the function calls, essentially making walkdocs behave like a map function applied on each of the HTML files.\n\nwalkdocs(directory_root, filter = isdochtml) do fileinfo\n    @show fileinfo.fullpath\nend\n\n\n\n\n\n","category":"function"},{"location":"#MultiDocumenter","page":"MultiDocumenter","title":"MultiDocumenter","text":"","category":"section"},{"location":"","page":"MultiDocumenter","title":"MultiDocumenter","text":"This package aggregates Documenter.jl documentation from multiple sources into one page with a global search bar.","category":"page"},{"location":"#Example-usage","page":"MultiDocumenter","title":"Example usage","text":"","category":"section"},{"location":"","page":"MultiDocumenter","title":"MultiDocumenter","text":"using MultiDocumenter\n\nclonedir = mktempdir()\n\ndocs = [\n    MultiDocumenter.DropdownNav(\"Debugging\", [\n        MultiDocumenter.MultiDocRef(\n            upstream = joinpath(clonedir, \"Infiltrator\"),\n            path = \"inf\",\n            name = \"Infiltrator\",\n            giturl = \"https://github.com/JuliaDebug/Infiltrator.jl.git\",\n        ),\n        MultiDocumenter.MultiDocRef(\n            upstream = joinpath(clonedir, \"JuliaInterpreter\"),\n            path = \"debug\",\n            name = \"JuliaInterpreter\",\n            giturl = \"https://github.com/JuliaDebug/JuliaInterpreter.jl.git\",\n        ),\n    ]),\n    MultiDocumenter.MegaDropdownNav(\"Mega Debugger\", [\n        MultiDocumenter.Column(\"Column 1\", [\n            MultiDocumenter.MultiDocRef(\n                upstream = joinpath(clonedir, \"Infiltrator\"),\n                path = \"inf\",\n                name = \"Infiltrator\",\n                giturl = \"https://github.com/JuliaDebug/Infiltrator.jl.git\",\n            ),\n            MultiDocumenter.MultiDocRef(\n                upstream = joinpath(clonedir, \"JuliaInterpreter\"),\n                path = \"debug\",\n                name = \"JuliaInterpreter\",\n                giturl = \"https://github.com/JuliaDebug/JuliaInterpreter.jl.git\",\n            ),\n        ]),\n        MultiDocumenter.Column(\"Column 2\", [\n            MultiDocumenter.MultiDocRef(\n                upstream = joinpath(clonedir, \"Infiltrator\"),\n                path = \"inf\",\n                name = \"Infiltrator\",\n                giturl = \"https://github.com/JuliaDebug/Infiltrator.jl.git\",\n            ),\n            MultiDocumenter.MultiDocRef(\n                upstream = joinpath(clonedir, \"JuliaInterpreter\"),\n                path = \"debug\",\n                name = \"JuliaInterpreter\",\n                giturl = \"https://github.com/JuliaDebug/JuliaInterpreter.jl.git\",\n            ),\n        ]),\n    ]),\n    MultiDocumenter.MultiDocRef(\n        upstream = joinpath(clonedir, \"DataSets\"),\n        path = \"data\",\n        name = \"DataSets\",\n        giturl = \"https://github.com/JuliaComputing/DataSets.jl.git\",\n        # or use ssh instead for private repos:\n        # giturl = \"git@github.com:JuliaComputing/DataSets.jl.git\",\n    ),\n]\n\noutpath = joinpath(@__DIR__, \"out\")\n\nMultiDocumenter.make(\n    outpath,\n    docs;\n    search_engine = MultiDocumenter.SearchConfig(\n        index_versions = [\"stable\"],\n        engine = MultiDocumenter.FlexSearch\n    )\n)","category":"page"},{"location":"#Limiting-copied-versions-and-linking-to-all-upstream-versions","page":"MultiDocumenter","title":"Limiting copied versions and linking to all upstream versions","text":"","category":"section"},{"location":"","page":"MultiDocumenter","title":"MultiDocumenter","text":"When aggregating many packages, you can copy only selected deployed versions to reduce storage size of the final website:","category":"page"},{"location":"","page":"MultiDocumenter","title":"MultiDocumenter","text":"MultiDocumenter.MultiDocRef(\n    upstream = joinpath(clonedir, \"SomePackage\"),\n    path = \"SomePackage\",\n    name = \"SomePackage.jl\",\n    giturl = \"https://github.com/SomeOrg/SomePackage.jl.git\",\n    versions = MultiDocumenter.VersionSelection(\n        [\"stable\", \"dev\"];\n        # optional: adds a \"See All Versions\" entry to the version selector\n        all_versions_url = \"https://someorg.github.io/SomePackage.jl/\",\n    ),\n)","category":"page"},{"location":"","page":"MultiDocumenter","title":"MultiDocumenter","text":"Only the listed version directories are copied (plus root files like index.html and versions.js). Versions that do not exist upstream are reported and skipped; if none of them exist, all versions are copied.\nThe package's index.html is regenerated to redirect to the first version that was copied, and that version becomes the canonical one for the package, so list them in the order you want.\nversions.js is rewritten to include only copied versions, and Documenter's \"outdated version\" markers (DOCUMENTER_NEWEST, DOCUMENTER_STABLE) are repointed at versions that were copied.\nIf all_versions_url is set, the version selector gets a See All Versions entry pointing there, so that the versions that were not copied stay reachable on the upstream site. It must be an absolute http(s) URL naming the site root, and is not derived from giturl.","category":"page"},{"location":"","page":"MultiDocumenter","title":"MultiDocumenter","text":"(Image: example)","category":"page"},{"location":"#Deployment","page":"MultiDocumenter","title":"Deployment","text":"","category":"section"},{"location":"","page":"MultiDocumenter","title":"MultiDocumenter","text":"Check .github/workflows/deploy.yml and docs/make.jl for an example on how to deploy MultiDocumenter-generated aggregates to a git branch.","category":"page"},{"location":"","page":"MultiDocumenter","title":"MultiDocumenter","text":"The result of that script is available at https://juliacomputing.github.io/MultiDocumenter.jl/.","category":"page"},{"location":"","page":"MultiDocumenter","title":"MultiDocumenter","text":"You can of course also just push the output artefact directly to S3 or some other hosting service.","category":"page"},{"location":"","page":"MultiDocumenter","title":"MultiDocumenter","text":"Warning MultiDocumenter sites can not be deployed on Windows right now, and the make() function will throw an error. See #70.It is still possible to develop and debug MultiDocumenter sites on Windows if the build script is run interactively (e.g. by include-ing it into a REPL session).","category":"page"},{"location":"#Docstrings","page":"MultiDocumenter","title":"Docstrings","text":"","category":"section"},{"location":"","page":"MultiDocumenter","title":"MultiDocumenter","text":"Modules = [MultiDocumenter]","category":"page"},{"location":"#MultiDocumenter.DropdownComponent","page":"MultiDocumenter","title":"MultiDocumenter.DropdownComponent","text":"abstract type DropdownComponent\n\nThe supertype for any component that can be put in a dropdown column and rendered using MultiDocumenter.render(::YourComponent, thispagepath, dir, prettyurls).\n\nAll DropdownComponents go in Columns, which go in MegaDropdownNav.\n\nAny subtype of DropdownComponent must implement that render method.\n\nThe main subtype is MultiDocRef, which refers to external documentation and adds it to the search index.  However, there are others like Link which is used to link to external sites without making them searchable, and users can implement their own custom components.\n\n\n\n\n\n","category":"type"},{"location":"#MultiDocumenter.Link","page":"MultiDocumenter","title":"MultiDocumenter.Link","text":"Link([text::String], link::String, [isexternal::Bool]) <: DropdownComponent\n\nRepresents a link to an external site.\n\n\n\n\n\n","category":"type"},{"location":"#MultiDocumenter.MultiDocRef","page":"MultiDocumenter","title":"MultiDocumenter.MultiDocRef","text":"struct MultiDocRef <: DropdownComponent\nMultiDocRef(; upstream, name, path, giturl = \"\", branch = \"gh-pages\", fix_canonical_url = true, versions = nothing)\n\nRepresents one set of docs that will get an entry in the MultiDocumenter navigation.\n\nRequired arguments:\n\nupstream: the local directory where the documentation is located. If giturl is passed, MultiDocumenter will clone into this directory.\nname: string used in the MultiDocumenter navigation for this item\npath: the URL path under which the contents of upstream is placed\n\nOptional arguments:\n\ngiturl: URL of the remote Git repository that will be cloned. If this is unset, then upstream must be an existing directory.\nbranch: Git branch of giturl where the docs will be pulled from (defaults to gh-pages)\nfix_canonical_url: this can be set to false to disable the canonical URL fixing for this MultiDocRef (see also canonical_domain for make).\nversions: a VersionSelection, to copy only some of the deployed versions instead of the whole upstream tree. All versions are copied by default. Root files (e.g. index.html, versions.js) are always copied. When a selection is given, versions.js is rewritten to list only the copied versions, and DOCUMENTER_NEWEST / DOCUMENTER_STABLE are repointed at copied versions so that Documenter does not mark kept pages as outdated (and noindex) or link its banner at a version that is no longer there.\n\n\n\n\n\n","category":"type"},{"location":"#MultiDocumenter.SearchConfig","page":"MultiDocumenter","title":"MultiDocumenter.SearchConfig","text":"SearchConfig(index_versions = [\"stable\"], engine = MultiDocumenter.PageFind, lowfi = false)\n\nindex_versions is a vector of relative paths used for generating the search index. Only the first matching path is considered (except for PageFind, which indexes all of them). This is one global list, so a MultiDocRef that publishes none of these paths – e.g. because its VersionSelection keeps different ones – contributes nothing to the search index; MultiDocumenter warns about each such ref during the build. engine may be MultiDocumenter.PageFind, MultiDocumenter.FlexSearch, MultiDocumenter.Stork, or a module that conforms to the expected API (which is currently undocumented). lowfi = true will try to minimize search index size. Only relevant for flexsearch.\n\n\n\n\n\n","category":"type"},{"location":"#MultiDocumenter.VersionSelection","page":"MultiDocumenter","title":"MultiDocumenter.VersionSelection","text":"struct VersionSelection\nVersionSelection(versions; all_versions_url = nothing)\n\nSelects which deployed versions of a MultiDocRef are copied into the aggregate, and where the ones that are left out can still be found.\n\nAggregating packages with long gh-pages histories can push the combined site past a host's size limit (GitHub Pages allows 1 GB), and most of that history is rarely read. Copying only [\"stable\", \"dev\"] keeps the site small; all_versions_url then keeps the rest reachable.\n\nversions: the version directories to copy, e.g. [\"stable\", \"dev\"]. Entries that do not exist upstream are reported and skipped; if none of them exist, all versions are copied instead. The first version that was copied is what the ref's index.html redirects to and what MultiDocumenter treats as canonical, so the order matters.\nall_versions_url: absolute http(s) URL of the upstream documentation site root, e.g. https://org.github.io/Pkg.jl/. When given, a \"See All Versions\" entry pointing there is added to the version selector. Use the site root rather than a specific version: Documenter's selector tries to stay on the equivalent page, so it may append the current page's path to this URL.\n\nMultiDocumenter.VersionSelection(\n    [\"stable\", \"dev\"];\n    all_versions_url = \"https://org.github.io/Pkg.jl/\",\n)\n\n\n\n\n\n","category":"type"},{"location":"#MultiDocumenter.cp_select_versions-Tuple{String, String, Vector{String}}","page":"MultiDocumenter","title":"MultiDocumenter.cp_select_versions","text":"Copy all root files and the listed version directories from src to dst, skipping .git and any version directory not in versions.\n\nReturns the subset of versions that was actually copied, in the given order. Requested versions that are missing upstream, or are symlinks with no target left (which happens on gh-pages branches where old version directories were pruned by hand), are reported and skipped rather than aborting the build.\n\nEverything is copied with follow_symlinks = true, so that e.g. stable -> v5.5.0 becomes a real directory and the result does not depend on paths that were not copied.\n\n\n\n\n\n","category":"method"},{"location":"#MultiDocumenter.inject_see_all_versions_option!-Tuple{Gumbo.HTMLDocument, AbstractString}","page":"MultiDocumenter","title":"MultiDocumenter.inject_see_all_versions_option!","text":"Add a \"See All Versions\" entry to Documenter's version selector, pointing at url.\n\nDocumenter's own selector code (assets/html/js/versions.js) only ever appends to the selector – it never clears it, and it matches the versions from DOC_VERSIONS against existing options by their text. So an <option> written in at build time survives untouched and needs no client side code; it ends up above the versions Documenter fills in.\n\nSelecting it hands over to Documenter's own handler, which tries to stay on the same page: it appends the current path below the version directory to url, HEADs that, and falls back to url itself if the probe fails. url should therefore name a site root – point it at a specific version and a visitor of .../stable/man/guide.html may well land on .../<that version>/man/guide.html instead of the page you meant.\n\nPages without a version selector (e.g. the redirect stubs) are left alone.\n\n\n\n\n\n","category":"method"},{"location":"#MultiDocumenter.is_generated_redirect-Tuple{AbstractString}","page":"MultiDocumenter","title":"MultiDocumenter.is_generated_redirect","text":"Whether page is a generated redirect stub rather than a rendered documentation page.\n\nInjecting stylesheets and scripts into these would make a page whose only job is to redirect first fetch and run the whole aggregate front end, and would destroy the marker itself.\n\n\n\n\n\n","category":"method"},{"location":"#MultiDocumenter.make-Tuple{Any, Vector}","page":"MultiDocumenter","title":"MultiDocumenter.make","text":"make(\n    outdir,\n    docs::Vector{MultiDocRef};\n    assets_dir,\n    brand_image,\n    custom_stylesheets = [],\n    custom_scripts = [],\n    search_engine = SearchConfig(),\n    prettyurls = true,\n    rootpath = \"/\",\n    hide_previews = true,\n    canonical = nothing,\n)\n\nAggregates multiple Documenter.jl-based documentation pages docs into outdir.\n\nassets_dir is copied into outdir/assets\nbrand_image is a BrandImage(path, imgpath), which is rendered as the leftmost item in the global navigation\ncustom_stylesheets is a Vector{String} of relative stylesheet URLs injected into each page.\ncustom_scripts is a Vector{Union{String, Docs.HTML}}. Strings can be relative or absolute URLs, while Docs.HTML objects are inserted as the content of inline scripts.\nsearch_engine inserts a global search bar if not false. See SearchConfig for more details.\nprettyurls removes all index.html suffixes from links in the global navigation.\nrootpath is the path your site ends up being deployed at, e.g. /foo/ if it's hosted at https://bar.com/foo\nhide_previews removes preview builds from the aggregated documentation.\ncanonical_domain: determines the the schema and authority (domain) of the (e.g. https://example.org) deployed site. If set, MultiDocumenter will check and, if necessary, update the canonical URL tags for each package site to point to the correct place directory. Similar to the canonical argument of Documenter.HTML constructor, except that it should not contain the path component – that is determined from rootpath.\nsitemap, if enabled, will generate a sitemap.xml file at the root of the output directory. Requires canonical_domain to be set, since the sitemap is determined from canonical URLs.\nsitemap_filename can be used to override the default sitemap filename (sitemap.xml)\n\n\n\n\n\n","category":"method"},{"location":"#MultiDocumenter.newest_kept_version-Tuple{AbstractString, Vector{String}}","page":"MultiDocumenter","title":"MultiDocumenter.newest_kept_version","text":"The highest version number among the copied version directories, or nothing if none of them holds a release (e.g. only dev was kept, which never triggers the banner anyway).\n\n\n\n\n\n","category":"method"},{"location":"#MultiDocumenter.rewrite_stable_target!-Tuple{String, Vector{String}}","page":"MultiDocumenter","title":"MultiDocumenter.rewrite_stable_target!","text":"Point DOCUMENTER_STABLE in each copied siteinfo.js at a directory that still exists.\n\nDocumenter's \"older version\" banner links to ../$(DOCUMENTER_STABLE), which 404s if the stable directory was not among the copied versions.\n\n\n\n\n\n","category":"method"},{"location":"#MultiDocumenter.rewrite_versions_js-Tuple{String, Vector{String}}","page":"MultiDocumenter","title":"MultiDocumenter.rewrite_versions_js","text":"Rewrite versions.js so that the version selector only offers kept_versions, and so that DOCUMENTER_NEWEST names the newest version we kept.\n\nDOCUMENTER_NEWEST matters because Documenter's warner.js compares it against each directory's DOCUMENTER_CURRENT_VERSION and, on a mismatch, marks the page noindex and shows an \"older version\" banner. Left pointing at a version that was not copied, that de-indexes perfectly current pages.\n\n\n\n\n\n","category":"method"},{"location":"#MultiDocumenter.see_all_versions_url_for-Tuple{Dict{Vector{String}, String}, AbstractString}","page":"MultiDocumenter","title":"MultiDocumenter.see_all_versions_url_for","text":"The \"See All Versions\" URL that applies to the page at relative_path, if any.\n\nAt most one ref can match: two refs whose paths nest would copy over each other in make_output_structure to begin with.\n\n\n\n\n\n","category":"method"},{"location":"#MultiDocumenter.see_all_versions_urls-Tuple{Vector}","page":"MultiDocumenter","title":"MultiDocumenter.see_all_versions_urls","text":"Map the output subdirectory of each version-limited MultiDocRef to its \"See All Versions\" URL. Refs that copy all their versions get no entry: the point of the link is to reach the versions that were left out, and there are none.\n\n\n\n\n\n","category":"method"},{"location":"#MultiDocumenter.stable_target-Tuple{AbstractString, Vector{String}}","page":"MultiDocumenter","title":"MultiDocumenter.stable_target","text":"The copied directory that DOCUMENTER_STABLE should point at, if we can name one.\n\n\n\n\n\n","category":"method"},{"location":"#MultiDocumenter.version_of_directory-Tuple{AbstractString, AbstractString}","page":"MultiDocumenter","title":"MultiDocumenter.version_of_directory","text":"The version a copied version directory holds, as recorded in its siteinfo.js.\n\n\n\n\n\n","category":"method"},{"location":"#MultiDocumenter.warn_unindexed_refs-Tuple{Any, Vector, AbstractVector}","page":"MultiDocumenter","title":"MultiDocumenter.warn_unindexed_refs","text":"Warn about any MultiDocRef that will contribute nothing to the search index.\n\nSearchConfig.index_versions is a single global list, but each ref decides for itself which versions it publishes (see VersionSelection), so a ref can easily end up with none of the indexed version directories in its output. Its pages are then published and linked from the navigation, but unreachable through the search box – which is easy to miss, since nothing else about the build looks wrong.\n\n\n\n\n\n","category":"method"}]
}
